package com.textbook.rest.rmm;

import org.springframework.hateoas.EntityModel;
import org.springframework.hateoas.Link;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.*;

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping("/{id}")
    public EntityModel<Order> getOrder(@PathVariable Long id) {
        Order order = orderService.findById(id);

        // Level 3 RMM: HATEOAS implementation providing self-referencing and state-driven transition links
        EntityModel<Order> orderModel = EntityModel.of(order);

        orderModel.add(linkTo(methodOn(OrderController.class).getOrder(id)).withSelfRel());

        if (order.isCancelable()) {
            orderModel.add(linkTo(methodOn(OrderController.class).cancelOrder(id)).withRel("cancel-order"));
        }

        return orderModel;
    }
}
